four_call_destructured_for_each:
let [tests, lint, status, files] = await Promise.all([
  tools.exec_command({cmd:"python3 -m unittest",workdir:"/repo"}),
  tools.exec_command({cmd:"python3 resources/scripts/validate_skills.py",workdir:"/repo"}),
  tools.exec_command({cmd:"git status --short",workdir:"/repo"}),
  tools.exec_command({cmd:"rg --files resources/skills",workdir:"/repo"})
]);
[tests, lint, status, files].forEach(r => text(r.output));
